// Shared helpers for the qd_* sandbox tools. Pure JS, no network, no Node-only APIs
// (so the same code runs inside the platform's JavaScript sandbox).

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

/** Accept the raw HTTP tool result in any of the shapes the runtime produces. */
function unwrapList(raw) {
  if (raw == null) return null;
  let v = raw;
  if (typeof v === 'string') {
    try { v = JSON.parse(v); } catch (e) { return null; }
  }
  if (Array.isArray(v)) return v;
  if (typeof v === 'object') {
    // Runtime wraps an array result as { result: [...] }; an HTTP 404 arrives as { statusCode: 404, is_error: true }.
    if (v.is_error === true || (typeof v.statusCode === 'number' && v.statusCode >= 400)) return [];
    if (Array.isArray(v.result)) return v.result;
    if (Array.isArray(v.data)) return v.data;
    if (Array.isArray(v.body)) return v.body;
    if (v.body && typeof v.body === 'object' && Array.isArray(v.body.result)) return v.body.result;
    // A single record object
    if (v.patientName || v.questAccountNumber) return [v];
  }
  return null;
}

function digitsOnly(s) {
  return String(s == null ? '' : s).replace(/\D/g, '');
}

const DIGIT_WORDS = { zero: '0', oh: '0', o: '0', one: '1', two: '2', three: '3', four: '4', five: '5', six: '6', seven: '7', eight: '8', nine: '9' };

/** "one zero zero 1" -> "10001". Spoken digit words only; number words like "ten million" are left to the GATHER layer. */
function spokenDigits(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .replace(/[a-z]+/g, (w) => (Object.prototype.hasOwnProperty.call(DIGIT_WORDS, w) ? DIGIT_WORDS[w] : ' '))
    .replace(/\D/g, '');
}

/** Name normalization per brief §4.S3.5: lower-case, remove spaces, hyphens, apostrophes (straight and curly) and periods. */
function normalizeName(s) {
  return String(s == null ? '' : s).toLowerCase().replace(/[\s\-'’.]/g, '');
}

function normalizeLoose(s) {
  return String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

/** Parse YYYY-MM-DD (or ISO) into a UTC Date at midnight; returns null when invalid. */
function parseDate(s) {
  if (s == null) return null;
  const m = String(s).trim().match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return null;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  if (Number.isNaN(d.getTime())) return null;
  if (d.getUTCMonth() !== +m[2] - 1 || d.getUTCDate() !== +m[3]) return null;
  return d;
}

const MONTH_INDEX = {
  jan: 0, january: 0, feb: 1, february: 1, mar: 2, march: 2, apr: 3, april: 3, may: 4, jun: 5, june: 5, jul: 6, july: 6,
  aug: 7, august: 7, sep: 8, sept: 8, september: 8, oct: 9, october: 9, nov: 10, november: 10, dec: 11, december: 11,
};

/** Spoken day words to digits: "september thirtieth" -> "september 30", "twenty eighth of may" -> "28 of may". */
const DAY_UNITS = { first: 1, one: 1, second: 2, two: 2, third: 3, three: 3, fourth: 4, four: 4, fifth: 5, five: 5, sixth: 6, six: 6, seventh: 7, seven: 7, eighth: 8, eight: 8, ninth: 9, nine: 9 };
const DAY_TEENS = {
  tenth: 10, ten: 10, eleventh: 11, eleven: 11, twelfth: 12, twelve: 12, thirteenth: 13, thirteen: 13, fourteenth: 14, fourteen: 14,
  fifteenth: 15, fifteen: 15, sixteenth: 16, sixteen: 16, seventeenth: 17, seventeen: 17, eighteenth: 18, eighteen: 18,
  nineteenth: 19, nineteen: 19, twentieth: 20, thirtieth: 30,
};
function dayWordsToDigits(t) {
  return String(t)
    .replace(/\b(twenty|thirty)[ -](first|one|second|two|third|three|fourth|four|fifth|five|sixth|six|seventh|seven|eighth|eight|ninth|nine)\b/g,
      (m, tens, u) => String((tens === 'twenty' ? 20 : 30) + DAY_UNITS[u]))
    .replace(/\b(tenth|ten|eleventh|eleven|twelfth|twelve|thirteenth|thirteen|fourteenth|fourteen|fifteenth|fifteen|sixteenth|sixteen|seventeenth|seventeen|eighteenth|eighteen|nineteenth|nineteen|twentieth|thirtieth)\b/g,
      (m) => String(DAY_TEENS[m]))
    .replace(/\b(first|second|third|fourth|fifth|sixth|seventh|eighth|ninth)\b/g, (m) => String(DAY_UNITS[m]));
}

/**
 * Loose caller date: "2026-09-28", "9/28", "9/28/26", "Sept 28", "September 28th", "the 28th of September", "28 sep 2026".
 * A month-day without a year takes the current year, or the previous year when that date would be in the future
 * (collection dates are never in the future). Returns "YYYY-MM-DD" or null.
 */
function parseLooseDate(text, todayIso) {
  if (text == null) return null;
  const raw = String(text).trim();
  const strict = parseDate(raw);
  if (strict) return strict.toISOString().slice(0, 10);
  const t = dayWordsToDigits(raw.toLowerCase().replace(/[,.]/g, ' '))
    .replace(/(\d+)(st|nd|rd|th)\b/g, '$1').replace(/\s+/g, ' ').trim();
  const today = parseDate(todayIso) || new Date();
  let y = null; let m = null; let d = null;
  const slash = t.match(/\b(\d{1,2})[\/-](\d{1,2})(?:[\/-](\d{2,4}))?\b/);
  if (slash) {
    m = +slash[1] - 1; d = +slash[2];
    if (slash[3]) y = +slash[3] < 100 ? 2000 + +slash[3] : +slash[3];
  } else {
    const mn = t.match(/\b(january|jan|february|feb|march|mar|april|apr|may|june|jun|july|jul|august|aug|september|sept|sep|october|oct|november|nov|december|dec)\b/);
    if (!mn) return null;
    m = MONTH_INDEX[mn[1]];
    const after = t.slice(mn.index + mn[0].length).match(/^\s*(?:the\s+)?(\d{1,2})\b/);
    const before = t.slice(0, mn.index).match(/(\d{1,2})\s*(?:of\s+)?$/);
    if (after) d = +after[1]; else if (before) d = +before[1]; else return null;
    const yr = t.match(/\b(20\d{2})\b/);
    if (yr) y = +yr[1];
  }
  if (m == null || d == null || m < 0 || m > 11 || d < 1 || d > 31) return null;
  if (y == null) {
    y = today.getUTCFullYear();
    if (Date.UTC(y, m, d) > today.getTime()) y -= 1;
  }
  const dt = new Date(Date.UTC(y, m, d));
  if (Number.isNaN(dt.getTime()) || dt.getUTCMonth() !== m || dt.getUTCDate() !== d) return null;
  return dt.toISOString().slice(0, 10);
}

function daysBetween(fromDate, toDate) {
  return Math.round((toDate.getTime() - fromDate.getTime()) / 86400000);
}

/** Whole years between dob and today (UTC). */
function ageYears(dob, today) {
  let age = today.getUTCFullYear() - dob.getUTCFullYear();
  const m = today.getUTCMonth() - dob.getUTCMonth();
  if (m < 0 || (m === 0 && today.getUTCDate() < dob.getUTCDate())) age -= 1;
  return age;
}

function ordinal(n) {
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
}

/** "2026-09-28" -> "September 28th" (no year); withYear adds ", 2026". */
function spokenDate(iso, withYear) {
  const d = parseDate(iso);
  if (!d) return '';
  const base = MONTHS[d.getUTCMonth()] + ' ' + ordinal(d.getUTCDate());
  return withYear ? base + ', ' + d.getUTCFullYear() : base;
}

/** Last 4 digits of a fax/phone number, as "0 1 7 1" for TTS. */
function last4(num) {
  const d = digitsOnly(num);
  return d.slice(-4);
}

function spokenDigitsSpaced(d) {
  return String(d || '').split('').join(' ');
}

function err(reason, extra) {
  return Object.assign({ status: 'ERROR', reason }, extra || {});
}

