/**
 * qd_classify_title
 * input : { titleText }
 * output: { status: AUTHORIZED|UNAUTHORIZED|UNKNOWN|ERROR, matched, category }
 *
 * Rules (config/title-lists.json _rules): unauthorized wins on conflict ("doctor's wife" contains "doctor");
 * PSR / "patient service representative" are UNAUTHORIZED; lists change only through Quest.
 * Matching: normalize the utterance (case, curly quotes, hyphens, punctuation, plurals), strip lead-ins/trailers, then
 * (1) a listed title said as such, unauthorized before authorized, (2) any unauthorized phrase anywhere in the text,
 * (3) the longest authorized title that ends the utterance ("I'm the office manager").
 * Short abbreviations (< 3 chars, "ma", "rn", "pa") need an exact answer.
 */

function normalize(raw) {
  return String(raw == null ? '' : raw)
    .toLowerCase()
    .replace(/[’‘`]/g, "'")
    .replace(/&/g, ' and ')
    .replace(/-/g, ' ')
    .replace(/[^a-z0-9\/' ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** "LVN (Licensed Vocational Nurse) case manager" -> abbreviation form, expansion form and the entry read out in full. */
function expandEntry(entry) {
  const out = new Set();
  const m = String(entry).match(/^(.*?)\s*\(([^)]*)\)\s*(.*)$/);
  const bases = m ? [`${m[1]} ${m[3]}`, `${m[2]} ${m[3]}`, String(entry)] : [String(entry)];
  for (const b of bases) {
    const n = normalize(b);
    if (!n) continue;
    out.add(n);
    if (n.includes('/')) {
      out.add(n.replace(/\//g, ''));          // ob/gyn -> obgyn
      out.add(n.replace(/\//g, ' '));         // x/y -> x y
      n.split('/').map((p) => p.trim()).filter(Boolean).forEach((p) => out.add(normalize(p)));
    }
  }
  return Array.from(out);
}

const UNAUTHORIZED = Array.from(new Set(TITLE_LISTS.unauthorized.flatMap(expandEntry)));
const AUTHORIZED = {};
for (const [category, titles] of Object.entries(TITLE_LISTS.authorized)) {
  for (const t of titles) {
    for (const v of expandEntry(t)) if (!Object.prototype.hasOwnProperty.call(AUTHORIZED, v)) AUTHORIZED[v] = category;
  }
}
const AUTHORIZED_KEYS = Object.keys(AUTHORIZED);

const LEAD_INS = /^(uh+|um+|ah|oh|so|well|yeah|yes|okay|ok|right now|currently|actually|i think|i am|i'm|im|i work as|it's|its|my title is|my job title is|my role is|we are|this is|i'm the|i am the|i'm a|i'm an|i am a|i am an)\s+/;
const TRAILERS = /\s+(here|working here|working at the office|working at the practice|in the office|at this office|at the office|at the practice|at the clinic|for the office|for the practice|for dr\.? \w+|for the doctor|for him|for her)$/;

function strip(value) {
  let v = value;
  for (let i = 0; i < 3; i += 1) {
    v = v.replace(LEAD_INS, '').replace(/^(a|an|the|one of the|just a|just the)\s+/, '').replace(TRAILERS, '').trim();
  }
  return v;
}

/** Singular variants: "nurses" -> "nurse", "patient services representative" -> "patient service representative". */
function singulars(text) {
  const out = new Set([text]);
  if (/s$/.test(text) && !/ss$/.test(text)) out.add(text.replace(/s$/, ''));
  out.add(text.replace(/\b(\w+)s (?=\w)/g, (m, w) => (w.length > 3 ? `${w} ` : m)));
  return Array.from(out);
}

function escapeRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function phraseIn(text, phrase) { return new RegExp('(^|[^a-z0-9])' + escapeRe(phrase) + '([^a-z0-9]|$)').test(text); }
function phraseEnds(text, phrase) { return new RegExp('(^|[^a-z0-9])' + escapeRe(phrase) + '$').test(text); }

function run(input) {
  if (!input || typeof input !== 'object') return err('INPUT_NOT_OBJECT');
  const raw = input.titleText;
  if (raw == null || String(raw).trim() === '') return { status: 'UNKNOWN', matched: null, category: null };
  const text = normalize(raw);
  const candidates = Array.from(new Set([text, strip(text)].flatMap(singulars)));

  // 1) A title that is itself on a list, said as such: unauthorized first ("doctor's wife" beats "doctor"), then
  //    authorized ("other office representative" is a listed title even though bare "representative" is not allowed).
  for (const c of candidates) {
    if (UNAUTHORIZED.includes(c)) return { status: 'UNAUTHORIZED', matched: c, category: null };
  }
  for (const c of candidates) {
    if (Object.prototype.hasOwnProperty.call(AUTHORIZED, c)) return { status: 'AUTHORIZED', matched: c, category: AUTHORIZED[c] };
  }
  // 2) Otherwise an unauthorized phrase anywhere in the utterance wins ("an intern with the nurse").
  for (const u of UNAUTHORIZED) {
    if (candidates.some((c) => phraseIn(c, u))) return { status: 'UNAUTHORIZED', matched: u, category: null };
  }
  // 3) Authorized phrase that ENDS the utterance ("we're the front desk"); never mid-sentence ("the doctor's cousin").
  let best = null;
  for (const key of AUTHORIZED_KEYS) {
    if (key.length < 3) continue;
    if (candidates.some((c) => phraseEnds(c, key)) && (!best || key.length > best.length)) best = key;
  }
  if (best) return { status: 'AUTHORIZED', matched: best, category: AUTHORIZED[best] };
  return { status: 'UNKNOWN', matched: null, category: null };
}

